public class Main {
    public static String check(int n) {
        if (n > 0) {
            return "还有数据";
        }
        System.out.println("这句只在没结果可返回的时候才轮到");
        return "元素空了";
    }

    public static void main(String[] args) {
        System.out.println(check(5));
        System.out.println(check(0));
    }
}

